from src.attendance_system import AttendanceSystem


class TestAttendanceTADDoubleLinkList:
    
    def test_issue_ticket_tad_double_link_list(self, att_system_tad_double_link_list: AttendanceSystem, test_data):
        for person in test_data["test_issue_ticket"]["priority"]:
            _person = att_system_tad_double_link_list.issue_ticket(
                phone=person["phone"],
                attendance_type=person["att_type"],
                bi=person["bi"],
                name=person["name"]
            
            )
            assert person["bi"] == _person.bi
            assert person["name"] == _person.name
            assert person["phone"] == _person.phone
            assert person["att_type"] == _person.type
            
        for person in test_data["test_issue_ticket"]["normal"]:
            _person = att_system_tad_double_link_list.issue_ticket(
                phone=person["phone"],
                attendance_type=person["att_type"],
                bi=person["bi"],
                name=person["name"]
            )
            assert person["bi"] == _person.bi
            assert person["name"] == _person.name
            assert person["phone"] == _person.phone
            assert person["att_type"] == _person.type

    def test_call_next_tad_double_link_list(self, att_system_tad_double_link_list: AttendanceSystem, test_data):
        person = att_system_tad_double_link_list.call_next()
        assert person.name == test_data["test_issue_ticket"]["priority"][0]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["priority"][0]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["priority"][0]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["priority"][0]["phone"]
        assert person.type == test_data["test_issue_ticket"]["priority"][0]["att_type"]
        
        person = att_system_tad_double_link_list.call_next()
        assert person.name == test_data["test_issue_ticket"]["priority"][1]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["priority"][1]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["priority"][1]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["priority"][1]["phone"]
        assert person.type == test_data["test_issue_ticket"]["priority"][1]["att_type"]
        
        person = att_system_tad_double_link_list.call_next()
        assert person.name == test_data["test_issue_ticket"]["normal"][0]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["normal"][0]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["normal"][0]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["normal"][0]["phone"]
        assert person.type == test_data["test_issue_ticket"]["normal"][0]["att_type"]
        
        person = att_system_tad_double_link_list.call_next()
        assert person.name == test_data["test_issue_ticket"]["priority"][2]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["priority"][2]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["priority"][2]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["priority"][2]["phone"]
        assert person.type == test_data["test_issue_ticket"]["priority"][2]["att_type"]
    
    def test_get_queues_tad_double_link_list(self, att_system_tad_double_link_list: AttendanceSystem, test_data):
        test_data = {
            "normal": test_data["test_issue_ticket"]["normal"][1:],
            "priority": test_data["test_issue_ticket"]["priority"][3:]
        }
        all_queues = att_system_tad_double_link_list.get_queues()
        
        total = len(all_queues["priority"]) + len(all_queues["normal"])
        test_data_total = len(test_data["priority"]) + len(test_data["normal"]) 
        
        assert len(all_queues["priority"]) == len(test_data["priority"])
        assert len(all_queues["normal"]) == len(test_data["normal"])
        assert total == test_data_total
        
        for person, v_person in zip(all_queues["normal"], test_data["normal"]):
            assert person[1] == v_person["name"]
            assert person[0] == v_person["ticket"]
            assert person[2] == v_person["att_type"]
        
        for person, v_person in zip(all_queues["priority"], test_data["priority"]):
            assert person[1] == v_person["name"]
            assert person[0] == v_person["ticket"]
            assert person[2] == v_person["att_type"]
            
    def test_search_ticket_tad_double_link_list(self, att_system_tad_double_link_list: AttendanceSystem, test_data):
        result = att_system_tad_double_link_list.search_ticket(
            test_data["test_issue_ticket"]["priority"][0]["ticket"])
        assert result == None
        
        result = att_system_tad_double_link_list.search_ticket(
            test_data["test_issue_ticket"]["priority"][6]["ticket"])
        
        assert result[1].name == test_data["test_issue_ticket"]["priority"][6]["name"]
        assert result[1].ticket == test_data["test_issue_ticket"]["priority"][6]["ticket"]
        assert result[0] == "priority"
        
        result = att_system_tad_double_link_list.search_ticket(
            test_data["test_issue_ticket"]["normal"][6]["ticket"])
        
        assert result[1].name == test_data["test_issue_ticket"]["normal"][6]["name"]
        assert result[1].ticket == test_data["test_issue_ticket"]["normal"][6]["ticket"]
        assert result[0] == "normal"
        
    def test_statistics_tad_double_link_list(self, att_system_tad_double_link_list: AttendanceSystem, test_data):
        stats = att_system_tad_double_link_list.statistics()
        assert stats == test_data["test_statistics"]["1"]
        
    def test_remove_ticket_tad_double_link_list(self, att_system_tad_double_link_list: AttendanceSystem, test_data):
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][20]["ticket"])
        assert result == True
        
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][1]["ticket"])
        assert result == True
        
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][21]["ticket"])
        assert result == True
        
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][2]["ticket"])
        assert result == True
        
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][1]["ticket"])
        assert result == False
        
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][3]["ticket"])
        assert result == True
        
        result = att_system_tad_double_link_list.remove_ticket(
            test_data["test_issue_ticket"]["normal"][3]["ticket"])
        assert result == False
